class IncorrectAlias(Exception):
    """ Signal analyzer alias is invalid """


class UnsupportedSignalAnalyzer(Exception):
    """ Given model of signal analyzer is not supported """


class DeviceLocked(Exception):
    """ Signal analyzer is locked for usage by other user  """


class CannotUnlockDevice(Exception):
    """ Device is still locked after attempt to unlock it """


class UnsupportedOperation(Exception):
    """ Operation is not supported by given model of signal analyzer """


class IncorrectOperation(Exception):
    """ Signal analyzer operation is invalid """


class IncorrectResponse(Exception):
    """ Response from signal analyzer is invalid """


class InternalError(Exception):
    """ Implementation of signal analyzer contains an error or unhandled situation """
